        "開幕遠Sや2Sを振るアクセルには、開幕ガード→ガード後に前ダッシュで距離を詰める。遠Sはガード後にアクセルが有利ではないので、ガード後が接近のチャンス。",
        "開幕バクステで距離を取るアクセルには、開幕前ジャンプで空中から距離を詰める。地上ダッシュは2Sに引っかかる。"
