        "鎌閃撃（236S）はガードさせた後に派生（8派生 Soaring Chain Strike=上方向、2派生 Spinning Chain Strike=下段）があり、派生前に前ジャンプすると8派生に、立っていると2派生に当たる危険がある。鎌閃撃はガードを固定し、派生を見てから動く。派生が出なかった時はアクセルの硬直に歩いて詰める。",
        "中距離（アクセルの5H・遠Sが届く距離）：ここが最も危険で、アクセルはこの距離で遠S→5Hのカウンターヒットを狙う。ジャンプは2Hや6P、雨水（214S、上方向に強い技）で落とされる。地上の歩きとガードで詰めるか、空ダをアクセルの技の硬直に合わせる。",
        "アクセルのジャンプ対策：アクセルは地上戦が強い代わりにジャンプを嫌うので、こちらが飛ぶとアクセルは2Hや6P、雨水で対空する。これらは発生が遅い技もあるので、ジャンプした後に空ダで軌道を変えるかFDで着地を安全にする。「ジャンプ→即空ダ」はアクセルの対空にかかりやすいので、「ジャンプ→様子見→着地」と「ジャンプ→空ダ」を使い分ける。",
        "アクセルのWinter Cherry（236S〜S、鎌閃撃から前方に長く伸びる派生。中段ではない）は中距離の押し付け技で、こちらが前に歩いた瞬間に当たる。しゃがみガードで防げる。ガード後はアクセルが有利ではないので前ダッシュで詰める。",
        "アクセルの蝸牛（214H）は鎖を振り上げてから前方に落とす中距離の技で、こちらの前進を止める。ガード後は −24 だが距離が離れやすく、A.B.Aの技が届くかは距離次第（要トレモ確認）。届かなければガードしてから前に歩く。",
        "近距離：アクセルは近づかれると弱い。近S・2K・5Pで触ると、アクセルはバクステ、6P、冬蟷螂（41236H、発生28Fの下段。しゃがみガード可だがガード後 +5〜+24 と大幅有利）、アクセルボンバー（j.236H、空中からの切り返し）で逃げる。密着を取ったら、バクステを読んで遠Sや長い技で狩る。",
