        "雨水（214S）：上方向に強い対空技。地上の相手には当たりにくい。ガード後は +3 で相手有利。→ 雨水を振るアクセルには飛ばず、地上から歩いて詰める。空振りを見たらダッシュで接近。",
        "蝸牛（214H）：鎖を振り上げて前に落とす技。ガード後は −24 と大幅不利。→ 届く距離でガードしたら近S始動の大きな確反（距離次第、要トレモ確認）。先端で届かない時はガード後に前に歩く。空中版（j.214H）も −25。",
        "冬蟷螂（41236H）：長い間合いの下段（発生28F）。投げではなくしゃがみガードで防げるが、ガード後は +5〜+24 でアクセルが大幅有利。ヒットすると引き寄せられて大ダメージ。→ 固め中はしゃがみガードを崩さない。見えたらジャンプで避け、空振りしたら近S/2K始動で確反。ガードしてしまったら反撃せず、次の固めに備える。",
