        "ベータブレード（623S）：無敵の切り返し。→ 固め中に隙間を作らない。ガード後（−40）は着地に近S始動の最大確反。",
        "幻朧斬（63214S）：瞬間移動してから掴むコマンド投げ。発生がやや遅い。→ チップが中距離で止まったらジャンプかバクステ。空振りに近S/2K始動の最大確反。",
        "壁走り（画面端付近でダッシュ中に6）：壁を走って上から攻撃。→ 落下地点に6P/2Hを置く。落下攻撃をガードしたら着地に確反。",
        "残星狼牙（632146H）：覚醒必殺技（発生20+1F）。ガード時のフレームはデータに無い。→ ゲージ50%以上のチップの前で中距離の技を雑に振らない。ガード後に反撃できるかは要トレモ確認。",
        "万鬼滅砕（236236P）：連続攻撃の覚醒必殺技。→ 発生が早い（6+1F）ので見てから潰すのは難しい。基本はガード。ガードしたら −20 なので近S始動で確反。",
        "Shuriken（j.214P、手裏剣）：空中から投げる飛び道具。ガード後は −34（最低空）と大幅不利。→ 低空で撃たれたらガード後に近S始動の大きな確反。高い位置からなら着地に向かってダッシュ。"
