        "チップの投げは発生が早く、近Sや2Kの後に歩き投げが頻繫に来る。近Sや2Kをガードした直後に投げ抜けを仕込む。表裏の投げも投げ抜けで対応できるので、ガード方向を間違えても投げ抜けは入力する。",
