        "相手を壁に追い込んだ時：チップの切り返しはベータブレードと6P、壁走りでの脱出。壁際ではチップがジャンプで逃げようとするので、固めに6Pや2Hのジャンプ狩りを混ぜる。ベータブレードをガードしたら最大確反で一気にラウンドを決める。チップの体力は低いので、壁割りよりもコンボのダメージを優先してもよい。",
