        "ウィンガー（632146H）をガード or 空振り （−32） → 着地に近S始動の最大コンボ。",
        "アルテミス（214H）をガード後（−8） → 近S/2K始動。",
        "2Dを密着でガード後（−8） → 2K/近S始動。6P（−15）・6H（−8）をガード後も近S/2K始動。",
        "5Hを近距離でガード後（−8） → 2K/近S始動。",
        "タンデムトップS（236S）を近距離でガード後（−10） → 近S/2K始動。距離が離れている場合は届かないので反撃しない（距離次第、要トレモ確認）。",
        "アイアンセイバー（214P）をしゃがみガード後（−12） → 近S/2K始動（裏に抜けたらガード方向を切り替えてから）。"
