        "ミリアのジャンプを見てから対空技を出さない（遅れて負ける。ジャンプの出かかりに6Pを置く）。",
        "密着でミリアの打撃をガードした後に暴れない（近Sのカウンターヒットから壁割りされる。確反の場面でのみ技を出す）。",
        "ミリアの表裏にガード方向を合わせようとして慌てて動かない（1択の被ダメージは少ない。FDで距離を取るか、投げ抜けを仕込んで択を受ける）。",
