        "中距離：ラムの遠S（横に長い）と2H（しゃがみの突き、横に長い、発生遅め）、5H（大きく振る、発生は遅いが範囲が広い）が主力。これらは全て『ガード後の硬直が長い』ので、ガードを固めず、空振りを見て前ダッシュで潰す。",
        "遠Sと5Hは6Pで潰せる。ただし2Hは姿勢が低く6Pが空振りすることがあるので、2Hの間合いでは2Dや足払いを置くか、ジャンプで飛び越える。",
        "ラムの対空は6Pと2H、JS。空中ダッシュで接近すると6Pで落とされる。接近は『低ダ（低空ダッシュ）』より『地上ダッシュ→FDブレーキ』の方が安全。",
        "近距離：ラムの近Sは発生が速く、2Kは速い下段。密着ではこちらの最速技（2P/2K）と殴り合いになる。密着を取ったら投げと中段の二択で崩す方がラムの有利フレームを使わせない。",
        "ダウロ（623P・飛び上がり突き）はラムの対空（無敵の有無は要トレモ確認）。ジャンプ攻撃を重ねる時に食らう。空中からの接近は着地を散らす。",
        "エラルルーモ（214P→4P→4P）は3段の連続攻撃。1段目で止めることも派生させることもできる。1段目止めはガード後−8なので近Sが間に合う（距離次第、要トレモ確認）。派生が来たら2・3段目はガード後−21で大きな確反（溜め版はガードクラッシュで−5／−8）。",
        "シルドデトルーオ（214K・飛び上がって剣を叩きつける）：中段。ジャンプ攻撃をガードした後の下段のつもりでしゃがんでいると食らう。見てから立ちガード可能な速度なので、剣を振り上げるモーションを見たら立つ。"
