        "JS：空中で横に広い。飛び込みとして強い。→ 6Pで落とすか、先に上を向いた技（2Hなど）を出す。IAD（低空ダッシュ）からのJSはガード後+5でラム有利なので、ガード後は暴れない。",
        "モルトバート（236236S・覚醒）：剣を大きく振り下ろす、リーチが長い。ガード後は−38。→ 暗転見てからジャンプかバクステ。ガードしたら−38なので、ダッシュ近S等で大きな確反（距離次第、要トレモ確認）。",
        "カルヴァドス（632146H・覚醒）：巨大なビーム、発生は遅いが範囲が大きい。ガードさせて+16（ガードクラッシュ）で反撃不可。→ 暗転見てからジャンプかバクステ。ガードしたら削りが大きいのでFD。",
