        "6H：大きく振り下ろす、リーチ長。ガード後−2。→ 発生が遅いので見てからダッシュで潰すかジャンプ。ガードしても確反はないので反撃しない。",
        "2S：低姿勢の下段突き。6Pが空振りする。ガード後−11。→ しゃがみガードして近S始動で確反（距離次第、要トレモ確認）。",
        "2H：上方向への長い突き。対空用。ガード後−11。→ 空中ダッシュで接近しない。ガードしたら近S始動で確反、空振りしたら着地後に近S。",
        "2D：長い足払い。ガード後−7。→ 先端は距離的に届きにくいが、近距離でガードしたら2K。",
        "ざらめ雪（236S）：発生18〜29F、使うと血のゲージが溜まる。ガードさせて+5で名残雪有利。→ ガード後は暴れない。遠ければ前ダッシュで距離を詰める。",
        "冠雪（214H）：低姿勢の突進斬り（上段）。6Pは空振りする。ガード後−3で確反なし。→ 2Kや2Dで先に触る。ガードしたら暴れず次に備える。",
        "垂雪（623H→H）：無敵の対空アッパー、追加入力で2段目。1段目止めはガード後−7、2段目は中段（立ちガード）でガード後−16。→ 空中からの重ねは控える。ガードしたら近S始動で確反。2段目まで出たら大きな確反。",
        "不香（236K・前／214K・後）：瞬間移動。前は接近、後は離脱。→ 前不香は到達点に2Pや最速技を置く。後不香を見たら前ダッシュで追う。",
