        "優先順位：①ガード（近Sと2Kをしゃがみガード、JDが見えたら立つ） ②ジャンプ（コマンド投げを警戒、名残雪の血のゲージが高い時は優先度を上げる） ③A.B.Aには無敵の切り返しがないので、暴れは最小限にしてガードと投げ抜けを優先（テンションがあればDAA、バーストも選択肢）。",
