        "忘れ雪（632146S）ガード → −39、残雪（632146H）ガード → −66。どちらもダッシュ近S等で大きな確反（距離次第、要トレモ確認）。",
        "不香（236K）の到達点に2Pを置く → 2Pヒット後は小さなコンボ。",
