        "相手を壁に追い込んだ時：名残雪の切り返しは垂雪（無敵対空）と忘れ雪（覚醒）。地上で打撃を重ね、空中からの重ねは控える。垂雪を詐欺飛びで釣ってガードし確反（A.B.Aでの詐欺飛びのタイミングは要トレモ確認）。血のゲージが高い時の必殺技の制限は要トレモ確認。",
        "ゲージ・体力：名残雪はテンション50%で忘れ雪の切り返しがある。相手の血のゲージが高い時は必殺技が制限されるので、その時間に攻める。自分の体力リード時は遠距離で待ち、不香を誘う。"
