        "開幕6Pはジオの遠Sと5Hを潰すが、ジオの2Kやダッシュ近Sに負ける。開幕バクステはダッシュ近Sを空振りさせて硬直に反撃できる。",
        "ジオは開幕にTrovão（236K・前進する蹴り）を出すこともある。ガードさせて相手有利気味なので、開幕にガードしても反撃しない。"
