        "優先順位：①立ちガードで中段を見て2Kが見えたら下げる、Sol Poenteの表裏は位置を見る ②投げ抜け（近Sで止まった時） ③バクステ（ジオの近Sと2Kはリーチが短いので有効、ただしダッシュで追われる）。",
