        "中距離：ゴールドルイスの遠S（横に長い、ガード後−12）、5H（巨大な振り、発生遅め、ガード後−10）、2D（長いスライディング、下段、発生14F、ガード後−10）、6H（大きく振る、発生遅め、ガード後−14）、ビヒーモス・タイフーン（半回転＋H、8方向、巨大な範囲）が主力。遠Sは6Pで潰す。5Hと6Hは発生が遅いので見てからダッシュで潰す。2Dは低姿勢で6Pが空振りするので、2Kや足払いで先に触る。どれもリーチが長く、先端ガード後はA.B.Aの通常技が届かないことが多い。近めでガードできた時だけ近S始動（距離次第、要トレモ確認）。",
