        "ローリング移動（214K）：本体がヨーヨーの位置まで転がる。ヨーヨーが遠くにある時は瞬間移動に近い。ヨーヨー有りの転がりには攻撃判定があり、ガードさせられると +16 で相手有利。ヨーヨー無しなら全体50Fの移動技で終わり際に硬直があるので、着地点に近Sや投げを合わせる。ヨーヨーが設置されている時は『相手がどこに移動できるか』を常に意識。",
