        "接近手段の止め方：ブリジットの接近は低空ダッシュj.S（長い）、前ダッシュ近S、236Kの突進。j.Sは6Pで落とす。ダッシュ近Sは2Kや近Sで止める。236Kはしゃがみガードで受けて確反。",
