        "デジャヴ（call 0x$0.20、214P）：本体がデジャヴ入力をすると、設置物が再発動する。本体の硬直は全体30F。再発動した設置物はガードさせると +3（!P）〜+26（!S）で相手有利、!Hはガードクラッシュ属性なので、ガードした後は反撃しない。デジャヴは本体から離れた位置で発動するので、設置物と本体の間に立たないこと。",
