        "術を撃っている時にジャンプする（空中を狙う術と2Hに落とされる）。",
        "設置系の術の発動場所に入る（時間差で発動してコンボ始動を取られる）。",
        "ディスカード/ブックマークを見ても近づかない（手札が整い、術の圧力が上がる。必ずダッシュで殴る）。",
