        "起き上がり優先順位：しゃがみガード＞投げ抜け仕込み＞バクステ。A.B.Aには無敵の切り返しが無いので、起き上がりはガードと投げ抜けで凌ぐ。JR中に起き上がりで暴れると、読まれた時の被害が大きい。",
        "JR中の起き攻めはダッシュなどで表裏を狙ってくる（214Kの性能は要トレモ確認）。相手の位置を見てガード方向を切り替え、暴れない。JR中の236Kは中段なので起き上がりは立ちガードも混ぜる。JRが終わるまで凌ぐ方が得。",
