        "通常状態の5H（−15）・遠S（−11）ガード後 → 近S始動（遠S・5Hの先端ガード時は届かないので反撃せず前ダッシュで距離を詰める。距離次第、要トレモ確認）。JR中は −5 なので2P/5Pだけ。",
