        "相手を壁に追い込んだ時（通常状態）：A.B.Aは切り返しが6Pとバクステ頼みなので、下段と投げで強気に固める。ただし63214P（Changing and Swaying）などを出す隙を与えないよう、間を空けずに触り続ける。",
