        "It's Late（214P/K~S）：中段（ガード区分High）の浮かせ技でガードクラッシュ属性（発生17+21F）。→ 立ちガード必須。ガード後は −2 で確反なし。しゃがみガードで待つとこれで浮かされる。",
        "Bump Ahead（214P/K~K）：下段（ガード区分Low）の派生（発生17+13F）。→ しゃがみガード必須。ガード後は −2 で確反なし。It's Late（中段）との中下段択になるので、ステップ後すぐ来たら下段、遅ければ中段と判断する。",
        "Bloodsucking Universe（63214H）：発生7Fのコマンド投げで、吸血してスレイヤーの体力を回復。→ 見てからは避けられない。密着でガードを固めず、ジャンプ・バクステ・小技を混ぜる。空振りの硬直（48F）に着地近Sや前ダッシュ近Sで確反（避け方と距離次第、要トレモ確認）。",
        "5H：大振りのパンチ（発生13F）で、カウンターヒットから壁まで運ぶ。→ ガード後 −3 で反撃なし。手を出さず、空振りを誘って差し返す技。",
        "2H：低い姿勢の下段（ガード区分Low、発生13F、硬直37F）。対空技ではない。→ ガード後 −20 で大きな確反（近S始動）。しゃがみガードで受けて反撃。",
        "6H：長いストレートで火力の高い始動（発生19F）。→ ガード後 −7（条件付きで+3）。密着なら2K/近Sで確反、先端ガード時は届かないので反撃せず前ダッシュで距離を詰める。中距離で技を振るとこれがカウンターで刺さる。",
        "2D：発生の早い下段（10F）。→ ガード後 −8〜−3（先端ほど不利が小さい）。密着なら2Kで反撃可、先端は反撃不可。しゃがみガード安定。",
        "覚醒必殺技：Super Mappa Hunch（632146S：突進して殴り抜ける、発生14+1F、ガード後 −33）／Last Horizon（236236H：発生9+2F、ガード後 −10）。→ いずれもガード後は確反（632146Sは最大コンボ、236236Hは近S）。ゲージ50%以上の相手に密着で固めを続けると割り込まれる。",
        "Master's Hammer（214P/K~H）：Dandy Stepからの大振り（発生17+25F、ガードさせて+26のガードクラッシュ）。→ ガードすると大幅不利。発生が遅いので、ステップを見たら2P/5Kで止めるか、派生の遅さを見てバクステで空振りさせて確反。",
        "6K（発生28F、中段、ガードさせて+2）／Hand of Doom（44~6S：バクステからの踏み込み攻撃、発生12F、ガード後 −7）。→ 6Kは遅いので見てから立ちガード、ガード後は手を出さない。Hand of Doomは2K/近Sで確反。"
