        "暴れ所はMappa Hunch K（−6、小技のみ）、Pilebunker（−14）、2H（−20）、6H（−7）ガード後。それ以外（近S（+3）・遠S（+4）・5H（−3）・Mappa P（−3）・It's Late/Bump Ahead（−2）の後）は手を出さない。",
        "近S→遠Sの間に6P（発生11F）で割り込めるかは隙間の有無次第（要トレモ確認）で、スレイヤーの近S→投げやBloodsucking Universe（発生7F）と択になるので多用しない。",
        "FDは遠Sガード時に使ってマッパPの距離の外へ押し出す。ダンディステップ派生の前にFDすると派生が先端ガードになり反撃が届かなくなるので、ダンディステップ中はFDしない。",
