        "6H（−7）・Hand of Doom（44~6S、−7）ガード後 → 2K/近S始動（6Hの先端ガード時は届かないので反撃しない）。5H（−3）は反撃不可。",
        "Super Mappa Hunch（632146S）ガード後 −33、Last Horizon（236236H）ガード後 −10 → 近S始動。"
