        "起き上がり優先順位：しゃがみガード＞投げ抜け仕込み＞バクステ。設置物が重なっている時はバクステすると設置物に引っかかる。設置物が無い時はバクステで飛び道具の硬直を見てから動く。",
        "A.B.Aには無敵の切り返しが無いので、設置物を重ねられた起き上がりはガードと投げ抜けで凌ぎ、設置物の位置を見てガード方向を決める。",
        "ジャンプ表裏は設置物の攻撃判定中に来るので、相手の空中位置を見てガード方向を変える。迷ったら設置物側ではなく相手の着地側をガード。"
