        "飛んでくるボール：通常技やショットで飛ばされたボールは飛び道具扱い。→ ガードは安全。ボールをガードした有利Fで遠Sやショットが重なるので、ボールをガードした直後に動かない。",
        "遠S：長い横の牽制（発生11F）で、ボールに当てて飛ばす。→ ガード後 −8。密着なら2K/近Sで反撃可、先端は届かないので空振りを誘って差し返す。",
        "5H：長い横の大振り（発生13F）で、ボールに当てると強いショットになる。→ ガード後 −7。密着なら2K/近Sで反撃、先端ガード時は届かないので反撃せず前ダッシュで距離を詰める。",
